for(const [id,qty,cost,cat,nearFire]of [['arrows',20,{wood:4,stone:2},'supplies'],['ammo',20,{iron:3,coal:3},'supplies'],['cloth',3,{fiber:9},'supplies'],['bandage',3,{cloth:3,fiber:3},'supplies'],['potion',2,{berries:8,crystal:2,water:2},'supplies'],['cooked',2,{meat:2,wood:2},'food',true],['stew',2,{cooked:2,berries:6,water:2},'food',true],['fire',1,{wood:8,stone:4},'build'],['chest',1,{wood:15,stone:5},'build'],['turret',1,{iron:18,stone:12,gold:4},'build']])RECIPES.push({id,name:ITEMS[id].name+(qty>1?' ×'+qty:''),qty,cost,cat,nearFire:!!nearFire});
