function action(p,a){setContext(p);const idx=n=>Number.isInteger(n)&&n>=0&&n<SLOT_COUNT;if(a.op==='chat'){chat(p,a);return}if(a.op.startsWith('clan')){clanAction(p,a);return}if(a.angle!==undefined&&Number.isFinite(a.angle))p._input={...p._input,angle:clamp(a.angle,-Math.PI,Math.PI),distance:clamp(Number(a.distance)||85,65,165)};switch(a.op){case'select':if(idx(a.index))select(a.index+1);break;case'attack':attack();break;case'interact':interact();break;case'eat':eat();break;case'drink':drink();break;case'dismantle':dismantle();break;case'craft':{if(!Number.isInteger(a.recipe)||!RECIPES[a.recipe])break;const r=RECIPES[a.recipe],result=craftResult(r);if(result.ok){p.slots=result.slots;updateCounts();toast('Создано: '+r.name)}else toast(result.why);break}case'equip':if(idx(a.index))equipSlot(a.index);break;case'unequip':if(['head','body','shield','feet'].includes(a.key))unequip(a.key);break;case'use':if(typeof a.id==='string'&&Object.hasOwn(ITEMS,a.id)&&['food','heal','drink'].includes(ITEMS[a.id].kind))useItem(a.id);break;case'drop':if(idx(a.index)&&p.slots[a.index]){const s=p.slots[a.index];addDrop(s.id,s.qty,p.x+26,p.y+24);p.slots[a.index]=null;updateCounts()}break;case'move':if(idx(a.from)&&idx(a.to)){moveInventory(a.from,a.to);updateCounts()}break;case'appearance':if(validAppearance(a.appearance))p.appearance={skin:a.appearance.skin,suit:a.appearance.suit,tone:a.appearance.tone};break;case'transfer':{const b=state.builds.find(b=>b.id===a.chest&&b.type==='chest'&&b.hp>0);if(!b||dist(b,p)>90||lineBlocked(p,b)){toast('Подойди к сундуку');break}const from=a.direction==='store'?p.slots:a.direction==='take'?b.slots:null,to=from===p.slots?b.slots:p.slots;if(!from||!Number.isInteger(a.index)||a.index<0||a.index>=from.length)break;const s=from[a.index];if(!s)break;const left=putSlots(to,s.id,s.qty);from[a.index]=left?{id:s.id,qty:left}:null;updateCounts();break}}}
function publicPlayers(){return activePlayers().map(p=>({id:p.id,x:p.x,y:p.y,angle:p.angle,nick:p.nick,char:p.char,appearance:p.appearance,hp:p.hp,maxHp:p.maxHp,equipment:p.equipment,heldId:p.slots[p.active]?.id||null,clanId:clanOf(p)?.id||null,clanTag:clanOf(p)?.tag||'',spawnShield:p.spawnShield||0,blocking:p.blocking,swing:p.swing||0,walk:p.walk||0,flash:p.flash||0}));}
function personal(p){const out={...p,clanId:clanOf(p)?.id||null,coins:p.coins||0};delete out._input;return out;}
function initial(p){return{version:3,worldSize:WORLD,layoutVersion:2,chunks:state.chunks,p:personal(p),camp:state.camp,lakes:state.lakes,nodes:state.nodes,builds:state.builds,loot:state.loot,entities:state.entities,projectiles:state.projectiles,particles:[],time:state.time,day:state.day,deaths:p.deaths||0,bossDefeated:state.bossDefeated,boarDefeated:state.boarDefeated,bossActive:state.bossActive,spawn:5};}
let nodePrevious=new Map();function nodeChanges(){const out=[];state.nodes.forEach((n,i)=>{const key=n.hp+':'+(n.respawn>0)+':'+(n.hit>0);if(nodePrevious.get(i)!==key){out.push({index:i,...n});nodePrevious.set(i,key)}});return out;}
function frame(p,nodes){return{lakes:state.lakes,social:social(p),p:personal(p),players:publicPlayers(),entities:state.entities,builds:state.builds,loot:state.loot,projectiles:state.projectiles,time:state.time,day:state.day,bossDefeated:state.bossDefeated,boarDefeated:state.boarDefeated,bossActive:state.bossActive,nodes};}
function savedWorld(){const out=initial(starter);out.projectiles=[];out.clans=clans;return out;}
function expandBorders(){}
function restore(world){migrationOffset=world.layoutVersion===2?0:6500;world=JSON.parse(JSON.stringify(world));if(migrationOffset){for(const k of ['nodes','builds','entities','loot','lakes'])for(const a of world[k]||[]){a.x+=6500;a.y+=6500}world.p.x+=6500;world.p.y+=6500;world.camp.x+=6500;world.camp.y+=6500;}state=normaliseSave(world);state.chunks=Array.isArray(world.chunks)?world.chunks.filter(k=>typeof k==='string'&&/^\d+,\d+$/.test(k)):[];state.layoutVersion=2;state.builds=state.builds.filter(b=>!(world.builds.find(v=>v.x===b.x&&v.y===b.y)?.owner==='camp'&&b.type==='fire'));clans=Array.isArray(world.clans)?world.clans.filter(c=>typeof c.id==='string'&&Array.isArray(c.members)).map(c=>({...c,invites:[]})):[];state.builds.forEach(b=>{const raw=world.builds.find(v=>v.x===b.x&&v.y===b.y&&v.type===b.type);b.id=typeof raw?.id==='string'&&/^b[0-9]+$/.test(raw.id)?raw.id:'b'+(++buildId);buildId=Math.max(buildId,Number(b.id.slice(1))||0);b.owner=typeof raw?.owner==='string'?raw.owner:'camp';b.maxHp=WALLS[b.type]?.hp||b.hp;});state.worldSize=WORLD;nodeGrid=null;}
function validatePlayer(p){p={...p};if(migrationOffset&&p.mapVersion!==2){p.x+=migrationOffset;p.y+=migrationOffset;}Object.assign(p,projectLand(p.x,p.y));p.mapVersion=2;const w=savedWorld();w.p=p;const v=normaliseSave(w).p;v.id=p.id;v.deaths=p.deaths||0;v.coins=Number.isSafeInteger(p.coins)&&p.coins>=0?p.coins:0;v.pvpKills=p.pvpKills||0;v.spawnShield=5;v.mapVersion=2;return v;}
return{createPlayer,step,action,randomSpawn,ensureAround,initial,frame,nodeChanges,savedWorld,restore,validatePlayer,publicPlayers,social,get world(){return state}};
